ROOT = Path(CONFIG["root"])
START = time.monotonic()

def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                    ensure_ascii=False, allow_nan=False).encode()).hexdigest()

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def check(ok, reason):
    if not ok:
        raise ValueError(reason)

def save(name, value):
    path = ROOT / name
    tmp = path.with_name(path.name + ".tmp")
    with tmp.open("w", encoding="utf-8", newline="\n") as f:
        json.dump(value, f, sort_keys=True, indent=2, allow_nan=False)
        f.write("\n")
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)

def status(state, **extra):
    value = {"schema": "nexus.jump-distinct-host-verification.v1", "status": state,
             "source_sha": CONFIG["source_sha"], "lease_id": CONFIG["lease_id"],
             "checked_at_utc": datetime.now(timezone.utc).isoformat(),
             "elapsed_seconds": round(time.monotonic() - START, 3),
             "research_only": True, "auto_demo_promotion": False,
             "live_enabled": False, "official_coordinator_advanced": False, **extra}
    save("status.json", value)
    print(json.dumps(value, sort_keys=True), flush=True)

def git(*args, timeout=60):
    env = dict(os.environ, GIT_TERMINAL_PROMPT="0")
    result = subprocess.run([CONFIG["git_executable"], "-c", "credential.helper=",
                             "-c", "core.askPass=", *args], env=env, check=True,
                            capture_output=True, text=True, timeout=timeout)
    return result.stdout.strip()

def main():
    check(socket.gethostname().split(".")[0].upper() == CONFIG["qa_host"], "wrong QA host")
    check(CONFIG["qa_host"] != CONFIG["producer_host"], "QA host equals producer host")
    ROOT.mkdir(parents=True, exist_ok=False)
    with (ROOT / "execution.lock").open("x", encoding="utf-8") as f:
        f.write(str(os.getpid()) + "\n")
    save("launch-receipt.json", {"pid": os.getpid(), "source_sha": CONFIG["source_sha"],
                               "worker_sha256": sha(Path(__file__)), "qa_host": CONFIG["qa_host"],
                               "producer_host": CONFIG["producer_host"],
                               "config_digest": digest(CONFIG), "wall_seconds": 600})
    def deadline():
        status("FAILED_CLOSED", reason="600-second verifier deadline")
        os._exit(124)
    watchdog = threading.Timer(600, deadline)
    watchdog.daemon = True
    watchdog.start()
    exit_code = 1
    try:
        baseline = Path(CONFIG["existing_qa_root"])
        check(git("-C", str(baseline / "source"), "rev-parse", "HEAD") == CONFIG["parent_sha"],
              "existing baseline source changed")
        versions = {name: importlib.metadata.version(name) for name in CONFIG["runtime_pins"]}
        check(versions == CONFIG["runtime_pins"], "decoder/runtime version changed")
        archive = baseline / "dataset" / "canonical"
        raw = list(archive.rglob("*.parquet"))
        expected_raw = {r["raw_file_sha256"] for r in CONFIG["decoded_input"]["frames"]}
        check(len(raw) == 6 and {sha(p) for p in raw} == expected_raw, "canonical archive changed")
        old_ledger = baseline / "producer" / "novelty-ledger.json"
        check(sha(old_ledger) == CONFIG["prior_ledger_file_sha256"], "previous ledger changed")
        status("STAGING_EXACT_SOURCE", raw_files_verified=6, runtime_versions=versions)
        source = ROOT / "source"
        git("clone", "--shared", "--no-checkout", str(baseline / "source"), str(source))
        git("-C", str(source), "fetch", "--no-tags", "--depth", "1", CONFIG["repository_url"],
            CONFIG["source_sha"], timeout=90)
        git("-C", str(source), "checkout", "--detach", CONFIG["source_sha"])
        check(git("-C", str(source), "rev-parse", "HEAD") == CONFIG["source_sha"], "source HEAD mismatch")
        check(git("-C", str(source), "rev-parse", "HEAD^{tree}") == CONFIG["source_tree"], "source tree mismatch")
        check(not git("-C", str(source), "status", "--porcelain"), "source is dirty")
        producer = ROOT / "producer"
        producer.mkdir()
        for name, payload in CONFIG["immutable_files"].items():
            value = base64.b64decode(payload["base64"], validate=True)
            check(hashlib.sha256(value).hexdigest() == payload["sha256"], "transfer digest mismatch: " + name)
            with (producer / name).open("xb") as f:
                f.write(value)
        shutil.copyfile(old_ledger, producer / "previous-ledger.json")
        (ROOT / "tmp").mkdir()
        tempfile.tempdir = str(ROOT / "tmp")
        sys.path.insert(0, str(source))
        os.environ["PYTHONDONTWRITEBYTECODE"] = "1"
        sys.dont_write_bytecode = True
        import nexus_agent_composite_runtime as runtime
        def offline(*args, **kwargs):
            raise RuntimeError("verification must use immutable offline archive")
        socket.socket = socket.create_connection = offline
        status("VERIFYING_INDEPENDENT_NUMERICAL_REPLAY", raw_files_verified=6,
               distinct_physical_host=True, older_v5_jobs_rerun=False,
               producer_job_rerun=False, prior_decoder_parity_digest=CONFIG["decoded_input"]["decoded_input_digest"])
        proof = runtime.verify_independently(
            archive_root=archive, previous_ledger=producer / "previous-ledger.json",
            source_sha=CONFIG["source_sha"], lease_id=CONFIG["lease_id"],
            result_dir=producer, output=producer / "qa-evidence.json")
        check(proof["independent_replay_matches"] is True, "numerical mismatch")
        for name, payload in CONFIG["immutable_files"].items():
            check(sha(producer / name) == payload["sha256"], "producer snapshot changed: " + name)
        check(sha(old_ledger) == CONFIG["prior_ledger_file_sha256"], "old ledger changed")
        check(not git("-C", str(source), "status", "--porcelain"), "source changed during replay")
        core = {"schema": "nexus.jump-distinct-host-verification-completion.v1",
                "qa_host": CONFIG["qa_host"], "producer_host": CONFIG["producer_host"],
                "source_sha": CONFIG["source_sha"], "source_tree": CONFIG["source_tree"],
                "lease_id": CONFIG["lease_id"], "qa_digest": proof["qa_digest"],
                "producer_report_digest": proof["producer_report_digest"],
                "immutable_file_sha256": {n:p["sha256"] for n,p in CONFIG["immutable_files"].items()},
                "prior_ledger_file_sha256": CONFIG["prior_ledger_file_sha256"],
                "distinct_physical_host": True, "independent_numeric_replay_complete": True,
                "independent_decimal_accounting_complete": False, "raw_files_verified": 6,
                "runtime_versions": versions, "research_only": True, "auto_demo_promotion": False,
                "live_enabled": False, "official_coordinator_advanced": False,
                "older_v5_jobs_rerun": False, "producer_job_rerun": False,
                "qualification": "NOT_QUALIFIED_NO_PRISTINE_FUTURE_HOLDOUT",
                "scope": "Distinct-host deterministic numerical reproduction with shared source/data; no independent accounting implementation, signal/market source or profitability proof."}
        save("verification-receipt.json", {**core, "verification_digest": digest(core)})
        status("INDEPENDENT_NUMERICAL_REPLAY_MATCHED_RESEARCH_ONLY", qa_digest=proof["qa_digest"])
        exit_code = 0
    except Exception as exc:
        status("FAILED_CLOSED", reason=type(exc).__name__ + ": " + str(exc))
        raise
    finally:
        watchdog.cancel()
        (ROOT / "process-exit.txt").write_text("NATIVE_EXIT=" + str(exit_code) + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()
